<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Auth,Csrf,Database,View};

final class MedicamentosController
{
 public function index():void { Auth::requireLogin(); $db=Database::connection(); $buscar=trim($_GET['q']??''); $cat=(int)($_GET['categoria']??0); $sql="SELECT m.*,c.nombre categoria,COALESCE(SUM(CASE WHEN l.estado='habilitado' AND l.fecha_vencimiento>CURDATE() THEN l.cantidad_disponible ELSE 0 END),0) stock FROM medicamentos m JOIN categorias c ON c.id=m.categoria_id LEFT JOIN lotes l ON l.medicamento_id=m.id WHERE 1"; $p=[]; if($buscar!==''){ $sql.=' AND (m.nombre LIKE ? OR m.codigo LIKE ? OR m.laboratorio LIKE ?)'; $like="%$buscar%"; array_push($p,$like,$like,$like); } if($cat){$sql.=' AND m.categoria_id=?';$p[]=$cat;} $sql.=' GROUP BY m.id ORDER BY m.nombre'; $s=$db->prepare($sql);$s->execute($p);$medicamentos=$s->fetchAll();$categorias=$db->query('SELECT * FROM categorias WHERE activo=1 ORDER BY nombre')->fetchAll(); View::render('medicamentos/index',compact('medicamentos','categorias','buscar','cat')); }
 public function form():void { Auth::requireAdmin();$db=Database::connection();$id=(int)($_GET['id']??0);$medicamento=null;if($id){$s=$db->prepare('SELECT * FROM medicamentos WHERE id=?');$s->execute([$id]);$medicamento=$s->fetch();if(!$medicamento){flash('danger','Medicamento no encontrado.');redirect('index.php?page=medicamentos');}}$categorias=$db->query('SELECT * FROM categorias WHERE activo=1 ORDER BY nombre')->fetchAll();View::render('medicamentos/form',compact('medicamento','categorias')); }
 public function save():void { Auth::requireAdmin();Csrf::enforce();$db=Database::connection();$id=(int)($_POST['id']??0);$data=['categoria'=>(int)($_POST['categoria_id']??0),'codigo'=>strtoupper(trim($_POST['codigo']??'')),'nombre'=>trim($_POST['nombre']??''),'concentracion'=>trim($_POST['concentracion']??''),'presentacion'=>trim($_POST['presentacion']??''),'laboratorio'=>trim($_POST['laboratorio']??''),'precio'=>filter_var($_POST['precio_venta']??null,FILTER_VALIDATE_FLOAT),'minimo'=>filter_var($_POST['stock_minimo']??null,FILTER_VALIDATE_INT)]; if(!$data['categoria']||$data['codigo']===''||$data['nombre']===''||$data['precio']===false||$data['precio']<0||$data['minimo']===false||$data['minimo']<0){flash('danger','Revisa los campos obligatorios.');redirect('index.php?page=medicamento-form'.($id?'&id='.$id:''));}
  $imagen=null;if(!empty($_FILES['imagen']['tmp_name'])){$f=$_FILES['imagen'];$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$permitidos=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($permitidos[$mime])||$f['size']>2097152){flash('danger','La imagen debe ser JPG, PNG o WEBP y pesar menos de 2 MB.');redirect('index.php?page=medicamento-form'.($id?'&id='.$id:''));}$imagen=bin2hex(random_bytes(12)).'.'.$permitidos[$mime];move_uploaded_file($f['tmp_name'],BASE_PATH.'/public/uploads/'.$imagen);}
  try{if($id){$sql='UPDATE medicamentos SET categoria_id=?,codigo=?,nombre=?,concentracion=?,presentacion=?,laboratorio=?,precio_venta=?,stock_minimo=?'.($imagen?',imagen=?':'').' WHERE id=?';$vals=[$data['categoria'],$data['codigo'],$data['nombre'],$data['concentracion']?:null,$data['presentacion']?:null,$data['laboratorio']?:null,$data['precio'],$data['minimo']];if($imagen)$vals[]=$imagen;$vals[]=$id;$db->prepare($sql)->execute($vals);}else{$db->prepare('INSERT INTO medicamentos(categoria_id,codigo,nombre,concentracion,presentacion,laboratorio,precio_venta,stock_minimo,imagen) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$data['categoria'],$data['codigo'],$data['nombre'],$data['concentracion']?:null,$data['presentacion']?:null,$data['laboratorio']?:null,$data['precio'],$data['minimo'],$imagen]);}flash('success','Medicamento guardado correctamente.');}catch(\Throwable $e){flash('danger','No se pudo guardar. Verifica que el código sea único.');}redirect('index.php?page=medicamentos'); }
 public function toggle():void {Auth::requireAdmin();Csrf::enforce();$id=(int)($_POST['id']??0);Database::connection()->prepare('UPDATE medicamentos SET activo=1-activo WHERE id=?')->execute([$id]);flash('success','Estado actualizado.');redirect('index.php?page=medicamentos');}
}
